@@ -88,6 +88,10 @@ export type RawSlots = {

 const isInternalKey = (key: string) => key[0] === '_' || key === '$stable'

+// compiler generated markers on a compiled slots object
+// `_`: slot flag, `__`: cache indexes
+const isCompilerSlotMarker = (key: string) => key === '_' || key === '__'
+
 const normalizeSlotValue = (value: unknown): VNode[] =>
   isArray(value)
     ? value.map(normalizeVNode)
@@ -180,7 +184,11 @@ const assignSlots = (
     // when rendering the optimized slots by manually written render function,
     // do not copy the `slots._` compiler flag so that `renderSlot` creates
     // slot Fragment with BAIL patchFlag to force full updates
-    if (optimized || !isInternalKey(key)) {
+    //
+    // only skip the compiler markers (`_` and `__`) here, NOT every key that
+    // starts with an underscore: compiled slots may legitimately be named
+    // `_foo` (e.g. `<template #_foo>`) and must be copied over.
+    if (optimized || !isCompilerSlotMarker(key)) {
       slots[key] = children[key]
     }
   }
