@@ -311,4 +311,53 @@ describe('compiler + runtime integration', () => {
     app.mount(root)
     expect(root.innerHTML).toBe('<div>60000000100000111</div>')
   })
+
+  // regression: compiled slot names starting with an underscore were dropped
+  // when the child component was rendered in a non-optimized context (e.g.
+  // inside a parent slot that has a sibling conditional slot)
+  test('slot names starting with an underscore (sibling v-if slot)', () => {
+    const SubComponent = {
+      template: `<slot name="title"><i>default title</i></slot><slot name="_duration"><i>default duration</i></slot>`,
+    }
+    const BaseLayout = {
+      template: `<div><slot name="randomslotname"></slot><slot></slot></div>`,
+    }
+    const App = {
+      components: { SubComponent, BaseLayout },
+      data: () => ({ cond: true }),
+      template: `
+        <BaseLayout>
+          <template v-if="cond" #randomslotname><p>cond</p></template>
+          <SubComponent>
+            <template #title><b>title</b></template>
+            <template #_duration><b>duration</b></template>
+          </SubComponent>
+        </BaseLayout>`,
+    }
+    const root = document.createElement('div')
+    createApp(App).mount(root)
+    expect(root.innerHTML).toBe(
+      `<div><p>cond</p><b>title</b><b>duration</b></div>`,
+    )
+  })
+
+  test('dynamic slot with name starting with an underscore', async () => {
+    const Comp = {
+      template: `<slot name="_foo"><i>fallback</i></slot>`,
+    }
+    const App = {
+      components: { Comp },
+      data: () => ({ show: true }),
+      template: `<Comp><template v-if="show" #_foo><b>foo</b></template></Comp>`,
+    }
+    const root = document.createElement('div')
+    const vm: any = createApp(App).mount(root)
+    expect(root.innerHTML).toBe(`<b>foo</b>`)
+    vm.show = false
+    await nextTick()
+    expect(root.innerHTML).toBe(`<i>fallback</i>`)
+    vm.show = true
+    await nextTick()
+    expect(root.innerHTML).toBe(`<b>foo</b>`)
+  })
 })
